cd d:/applications/habit-tracker/backend && bun -e "
import { getDb, closeDb } from './src/db/index.ts';
import { habits, checkins } from './src/db/schema/index.ts';
import { eq } from 'drizzle-orm';

const db = getDb();
// clean slate
db.delete(checkins).run();
db.delete(habits).run();

const [h] = db.insert(habits).values({ name: 'Read', target: 30 }).returning().all();
console.log('inserted habit:', { id: h.id.slice(0,8), name: h.name, cadence: h.cadence, createdAt: h.createdAt instanceof Date });

db.insert(checkins).values({ habitId: h.id, date: '2026-07-02' }).run();
console.log('first check-in inserted OK');

let dupBlocked = false;
try { db.insert(checkins).values({ habitId: h.id, date: '2026-07-02' }).run(); }
catch (err) { dupBlocked = true; console.log('duplicate (habit,date) blocked:', err.message.split('\n')[0]); }
if (!dupBlocked) throw new Error('UNIQUE constraint did NOT block duplicate!');

// FK cascade: deleting habit removes its checkins
db.delete(habits).where(eq(habits.id, h.id)).run();
const remaining = db.select().from(checkins).all();
console.log('checkins after habit delete (cascade):', remaining.length);
if (remaining.length !== 0) throw new Error('FK cascade did not remove checkins!');

// FK enforcement: cannot insert checkin for missing habit
let fkBlocked = false;
try { db.insert(checkins).values({ habitId: 'does-not-exist', date: '2026-07-03' }).run(); }
catch (err) { fkBlocked = true; console.log('orphan check-in blocked:', err.message.split('\n')[0]); }
if (!fkBlocked) throw new Error('FK constraint did NOT block orphan checkin!');

closeDb();
console.log('ALL DOMAIN CONSTRAINTS VERIFIED');
"
